-- Designer's own pages, four levels down: where furni may move from.
DROP TABLE IF EXISTS `_dt_pages`;
CREATE TABLE `_dt_pages` (`id` INT NOT NULL PRIMARY KEY) ENGINE=InnoDB;
INSERT IGNORE INTO `_dt_pages` (`id`)
    SELECT `id` FROM `catalog_pages` WHERE `parent_id` = @designer AND `id` NOT BETWEEN 955000 AND 955999;
INSERT IGNORE INTO `_dt_pages` (`id`)
    SELECT c.`id` FROM `catalog_pages` c JOIN `_dt_pages` p ON c.`parent_id` = p.`id`;
INSERT IGNORE INTO `_dt_pages` (`id`)
    SELECT c.`id` FROM `catalog_pages` c JOIN `_dt_pages` p ON c.`parent_id` = p.`id`;
INSERT IGNORE INTO `_dt_pages` (`id`)
    SELECT c.`id` FROM `catalog_pages` c JOIN `_dt_pages` p ON c.`parent_id` = p.`id`;

DROP TABLE IF EXISTS `_dt_map`;
CREATE TABLE `_dt_map` (`furni_id` INT NOT NULL PRIMARY KEY, `page_id` INT NOT NULL) ENGINE=InnoDB;
