UPDATE `catalog_items` ci
  JOIN `_dt_pages` s ON s.`id` = ci.`page_id`
  JOIN `_dt_map` m ON CAST(m.`furni_id` AS CHAR) = ci.`item_id`
   SET ci.`page_id` = m.`page_id`;

-- The old pages once empty (84's and 92's ranges only), leaves before parents;
-- then any
-- new page nothing reached.
DELETE p FROM `catalog_pages` p JOIN `_dt_pages` s ON s.`id` = p.`id`
 WHERE (p.`id` BETWEEN 940002 AND 940999 OR p.`id` BETWEEN 942000 AND 942999)
   AND NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);
DELETE p FROM `catalog_pages` p JOIN `_dt_pages` s ON s.`id` = p.`id`
 WHERE (p.`id` BETWEEN 940002 AND 940999 OR p.`id` BETWEEN 942000 AND 942999)
   AND NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);
DELETE p FROM `catalog_pages` p JOIN `_dt_pages` s ON s.`id` = p.`id`
 WHERE (p.`id` BETWEEN 940002 AND 940999 OR p.`id` BETWEEN 942000 AND 942999)
   AND NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);
DELETE p FROM `catalog_pages` p
 WHERE p.`id` BETWEEN 955100 AND 955999
   AND NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`);
DELETE p FROM `catalog_pages` p
 WHERE p.`id` BETWEEN 955000 AND 955099
   AND NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);

